// The Galarian legendary birds (Articuno, Zapdos and Moltres's Galarian forms, from Sword and Shield: The Crown
// Tundra), added on request (2026-10-22). Real data: birds.json is generated by scripts/build-galar-birds-data.mjs.
// They learn the moves they learn in their debut game (Generation 8), Gen 8 moves included; those moves are theirs
// only. No simulator imports: the UI thread and the worker both build their data from this.
import birdsData from './birds.json';

const toId = (s: string) => s.toLowerCase().replace(/[^a-z0-9]/g, '');

export const GALAR_BIRDS = birdsData.species.map(s => s.name);
/** Each bird's moves (by species name): what it learns in Sword and Shield. */
export const GALAR_BIRD_MOVES: Record<string, string[]> = Object.fromEntries(birdsData.species.map(s => [s.name, s.moves]));
/** Gen 8 moves they learn that Gen 7 doesn't have: only the birds may use them. */
export const GALAR_BIRD_NEW_MOVES = birdsData.newMoves;
export const GALAR_BIRD_IDS = new Set(GALAR_BIRDS.map(toId));
export const GALAR_BIRD_NEW_MOVE_IDS = new Set(GALAR_BIRD_NEW_MOVES.map(toId));
const LEARNS = new Map(birdsData.species.map(s => [toId(s.name), new Set(s.moves.map(toId))]));

/** Whether a Galarian bird learns the move (null: not a Galarian bird). */
export function galarBirdCanLearn(speciesId: string, moveId: string): boolean | null {
  return LEARNS.get(speciesId)?.has(moveId) ?? null;
}

/**
 * Data layered on Showdown's Gen 7 data (as mod data, `inherit: true` entries): the birds and their Gen 8 moves stop
 * being "Future" (Showdown derives that from the entry's generation), and the birds aren't event-only (in Sword and
 * Shield they're wild encounters in The Crown Tundra; Showdown's events are from later generations).
 */
export function galarBirdsOverrides() {
  const species = Object.fromEntries(GALAR_BIRDS.map(n => [toId(n), { inherit: true, gen: 7 }]));
  const formatsData = Object.fromEntries(GALAR_BIRDS.map(n => [toId(n), { inherit: true, isNonstandard: null, tier: 'OU' }]));
  const learnsets = Object.fromEntries(GALAR_BIRDS.map(n => [toId(n), { inherit: true, eventOnly: false }]));
  const moves = Object.fromEntries(GALAR_BIRD_NEW_MOVES.map(n => [toId(n), { inherit: true, gen: 7, isNonstandard: null }]));
  return { Species: species, FormatsData: formatsData, Learnsets: learnsets, Moves: moves };
}
